```python
def transform(grid):
    if not grid or not grid[0]:
        return grid

    height, width = len(grid), len(grid[0])
    bg = grid[0][0]

    # Find all cells with non-background colors
    non_bg_cells = set()
    anchor_cols = []
    cells_by_type = {}

    for r in range(height):
        for c in range(width):
            val = grid[r][c]
            if val != bg:
                non_bg_cells.add((r, c))
                if val not in cells_by_type:
                    cells_by_type[val] = []
                cells_by_type[val].append((r, c))
                if val == list(cells_by_type.keys())[0]:
                    anchor_color = val

    if not cells_by_type:
        return grid

    # Most common non-bg color is anchor
    counts = {val: len(vals) for val, vals in cells_by_type.items()}
    anchor_color = max(counts, key=counts.get)

    # Get anchor column positions
    for r, c in cells_by_type.get(anchor_color, []):
        anchor_cols.append(c)

    if not anchor_cols:
        return grid

    min_c, max_c = min(anchor_cols), max(anchor_cols)
    axis_num = (min_c + max_c)  # Axis line at this value

    output = [row[:] for row in grid]

    for r in range(height):
        for c in range(width):
            val = grid[r][c]
            if val == bg or val == anchor_color:
                continue

            # Mirror position: if axis is between min_c and max_c, mirror across center
            # For 2w-wide block, the axis at center is (min_c+max_c)
            # The mirrored column is axis_num - c + 1 is not quite right
            # Actually: for 4 at cols 13-14, axis center is 13.5
            # Mirror: 2*13.5 - c = 27 - c
            # So formula is: 2*axis_num + 2*0.5 - wait that's messy

            # Simpler: axis center = (min_c + max_c) / 2
            # mirror = 2 * axis_center - c = (min_c + max_c) - c
            mirror_c = (min_c + max_c) - c
            if 0 <= mirror_c < width:
                output[r][mirror_c] = val

    return output
